DO $q$ declare profile_key uuid;parent_key uuid;started timestamptz;s jsonb;begin perform set_config('lock_timeout','3s',true); select p.id,p.parent_id into profile_key,parent_key from public.profiles p join public.parents h on h.id=p.parent_id where p.archived_at is null and p.session_mode='once' and h.timezone='America/New_York' and not exists(select 1 from public.child_sessions c where c.profile_id=p.id and c.revoked_at is null and c.timer_last_seen_at>clock_timestamp()-interval '30 seconds') order by p.id limit 1;if profile_key is null then perform set_config('watchnest.lock_b','{"skipped":true,"reason":"no_idle_profile"}',true);return;end if;started:=clock_timestamp();s:=public.wn_resolve_profile_session(parent_key,profile_key,false);perform set_config('watchnest.lock_b',jsonb_build_object('backend_pid',pg_backend_pid(),'attempted_at',started,'completed_at',clock_timestamp(),'server_snapshot_at',s->>'server_now','mode',s->>'mode','fingerprint',md5(profile_key::text||'WatchNest306LockProof'))::text,true);end $q$;select current_setting('watchnest.lock_b',true)::jsonb as proof;
